add_filter( 'woocommerce_loop_add_to_cart_link', 'perfectpixel_external_loop_new_tab', 20, 2 );
add_action( 'woocommerce_after_add_to_cart_button', 'perfectpixel_external_single_new_tab' );

function perfectpixel_external_loop_new_tab( $html, $product ) {
	if ( $product && $product->is_type( 'external' ) && false === strpos( $html, 'target=' ) ) {
		$html = preg_replace( '/^<a /', '<a target="_blank" rel="noopener noreferrer" ', $html );
	}
	return $html;
}

// The single external button is a GET form; make the form open in a new tab.
function perfectpixel_external_single_new_tab() {
	global $product;
	if ( $product && $product->is_type( 'external' ) ) {
		echo '<script>( function ( s ) { var f = s.closest( "form" ); if ( f ) { f.target = "_blank"; f.rel = "noopener"; } } )( document.currentScript );</script>';
	}
}
